import base64
from pathlib import Path
from app.config import BASE_DIR

WATERMARK_BASE64 = ""


def ensure_watermark_image() -> Path:
    target = BASE_DIR / "assets" / "watermark.png"
    if not target.exists() or target.stat().st_size == 0:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(WATERMARK_BASE64))

    app_target = BASE_DIR / "app" / "assets" / "watermark.png"
    if not app_target.exists() or app_target.stat().st_size == 0:
        app_target.parent.mkdir(parents=True, exist_ok=True)
        app_target.write_bytes(base64.b64decode(WATERMARK_BASE64))

    return target
